target.css:
:root {
  --ink: #17212b;
  --paper: #fffdf8;
  --line: #cdd5d8;
  --navy: #203a5f;
  --blue: #457b9d;
  --mint: #dceee8;
  --amber: #efa849;
  --cream: #f9f1dc;
  --soft: #eef3f4;
}

.rover-console {
  box-sizing: border-box;
  width: 500px;
  padding: 14px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--navy);
  border-radius: 16px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-copy p,
.header-copy h1 {
  margin: 0;
}

.eyebrow {
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.3px;
}

h1 {
  margin-top: 2px;
  font-size: 21px;
  line-height: 1.1;
  letter-spacing: -0.5px;
}

.status {
  padding: 5px 8px;
  color: var(--navy);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.console-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 10px;
  margin-top: 11px;
}

.sample-card,
.telemetry {
  box-sizing: border-box;
  min-height: 142px;
  border: 1px solid var(--line);
}

.sample-card {
  overflow: hidden;
  border-radius: 11px;
}

.sample-top {
  display: flex;
  justify-content: space-between;
  padding: 7px 9px;
  color: var(--navy);
  background: var(--cream);
  border-bottom: 1px solid var(--line);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.sample-code {
  color: var(--blue);
}

.sample-body {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px;
}

.core {
  display: grid;
  place-items: center;
  width: 66px;
  height: 66px;
  margin: 0;
  color: var(--paper);
  background: var(--navy);
  border: 5px solid var(--blue);
  border-radius: 50%;
  font-size: 31px;
  line-height: 1;
}

.readings {
  display: grid;
  flex: 1;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.readings li {
  display: flex;
  justify-content: space-between;
  padding-bottom: 4px;
  border-bottom: 1px dashed var(--line);
  color: var(--blue);
  font-size: 11px;
}

.readings strong {
  color: var(--ink);
  font-weight: 800;
}

.telemetry {
  padding: 10px;
  background: var(--soft);
  border-radius: 11px 11px 3px 11px;
}

.telemetry-head,
.signal-row,
.panel-footer,
.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.telemetry-head h2 {
  margin: 0;
  font-size: 13px;
  letter-spacing: -0.2px;
}

.telemetry-head span {
  padding: 2px 5px;
  color: var(--paper);
  background: var(--blue);
  border-radius: 3px;
  font-size: 9px;
  font-weight: 800;
}

.metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin: 10px 0;
}

.metric-grid div {
  padding: 6px 7px;
  background: var(--paper);
  border-left: 3px solid var(--amber);
}

dt {
  color: var(--blue);
  font-size: 10px;
}

dd {
  margin: 1px 0 0;
  color: var(--navy);
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}

.signal-row {
  font-size: 10px;
  font-weight: 700;
}

.signal-row strong {
  color: var(--navy);
}

.track {
  display: block;
  height: 6px;
  margin-top: 5px;
  overflow: hidden;
  background: var(--line);
  border-radius: 99px;
}

.track span {
  display: block;
  width: 62%;
  height: 100%;
  background: var(--amber);
  border-radius: inherit;
}

.panel-footer {
  margin-top: 10px;
}

.sync-note {
  color: var(--blue);
  font-size: 10px;
  font-weight: 600;
}

.controls {
  gap: 6px;
}

button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--navy);
  border: 1px solid var(--navy);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
}

button.outline {
  color: var(--navy);
  background: var(--paper);
}

